, added AS (
INSERT INTO public.store_products (business_id,category_id,nombre,nombre_en,precio,vendido_por_lb,peso_lb,unidad,subcategoria,descripcion,descripcion_en,imagen_url,orden,disponible)
SELECT b.id,c.id,v.nombre,v.nombre_en,v.precio,v.por_lb,v.peso,CASE WHEN v.por_lb THEN 'lb' ELSE 'unidad' END,v.subcategoria,v.descripcion,v.descripcion_en,'house/meat/2026-10-11/meat-'||lpad(v.n::text,2,'0')||'.jpg',399+v.n,true
FROM catalog v JOIN public.businesses b ON b.slug='hazorex-supermercado' JOIN public.store_categories c ON c.business_id=b.id AND c.nombre='Carnes y mariscos'
WHERE NOT EXISTS (SELECT 1 FROM public.store_products p WHERE p.business_id=b.id AND (lower(trim(p.nombre))=lower(trim(v.nombre)) OR lower(trim(p.nombre_en))=lower(trim(v.nombre_en))))
RETURNING id)
INSERT INTO public.store_product_sourcing(product_id,super,direccion) SELECT id,'Food Bazaar','' FROM added;